mapper.update:
UPDATE story
   SET title = #{title}
 WHERE story_id = #{storyId}

mapper.select:
SELECT 
  FROM story_node
 WHERE story_id = #{storyId}
   AND node_order = #{nodeOrder}
 ORDER BY node_id
 LIMIT 1

SELECT title
  FROM story
 WHERE child_id = #{childId}
   AND title IS NOT NULL
 ORDER BY story_id DESC
 LIMIT #{limit}

SELECT COUNT(*)
  FROM story
 WHERE child_id = #{childId}
   AND created_at >= #{from}
